1	package registrymgr
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"net/http"
8		"reflect"
9		"strings"
10		"testing"
11	
12		"github.com/anthnel/devdesk/internal/nexusfixture"
13		"github.com/anthnel/devdesk/internal/nexusfixture/fakenexus"
14		"github.com/anthnel/devdesk/internal/oci"
15	)
16	
17	// DEVDESK-511 (NX-08, step 5): DetectGroup walks the REST answers MEASURED on
18	// Nexus 3.98.1-01 (NX-03, DEVDESK-506, criterion 3 of the 2026-11-17 note),
19	// replayed by fakenexus, for the three bench accounts. The hand-written servers
20	// of nexus_members_test.go model what a Nexus could say; the verdicts below come
21	// from what this one did say, read in the fixtures (TestMeasuredRESTAnswersHoldThePremises
22	// pins the premises so that a re-recorded fixture that changes them fails here,
23	// not silently in a verdict).
24	//
25	// Out of scope, because no measured answer exists: a 5xx or an unreadable reply
26	// from a real Nexus, and the detailed endpoints of hosted and proxy (measured
27	// 404 and 403 but never asked by DevDesk: DetectGroup stops at the generic one).
28	
29	const (
30		restHost = "127.0.0.1:30481" // the REST API; hosted and proxy live here too
31	
32		restGroup  = "docker-group"
33		restHosted = "docker-hosted"
34		restProxy  = "docker-proxy"
35	)
36	
37	var restIdentities = []nexusfixture.Identity{nexusfixture.Admin, nexusfixture.Pull, nexusfixture.Anonymous}
38	
39	// restFixtures loads the catalog campaign, which holds the rest-* answers.
40	func restFixtures(t *testing.T) map[string]nexusfixture.Fixture {
41		t.Helper()
42		list, err := nexusfixture.Load("catalog")
43		if err != nil {
44			t.Fatalf("Load(catalog): %v", err)
45		}
46		byName := make(map[string]nexusfixture.Fixture, len(list))
47		for _, f := range list {
48			byName[f.Name] = f
49		}
50		return byName
51	}
52	
53	// genericFixture and detailedFixture name the recordings of
54	// GET /v1/repositories/{name} and GET /v1/repositories/docker/group/{name}.
55	func genericFixture(repo string, id nexusfixture.Identity) string {
56		return "rest-repositories-" + repo + "--" + string(id)
57	}
58	
59	func detailedFixture(repo string, id nexusfixture.Identity) string {
60		return "rest-repositories-group-" + repo + "--" + string(id)
61	}
62	
63	// restExchange returns the one exchange of a fixture, failing the test otherwise.
64	func restExchange(t *testing.T, fixtures map[string]nexusfixture.Fixture, name string) nexusfixture.Exchange {
65		t.Helper()
66		f, ok := fixtures[name]
67		if !ok {
68			t.Fatalf("fixture %s is missing from the catalog campaign", name)
69		}
70		if len(f.Exchanges) != 1 {
71			t.Fatalf("fixture %s has %d exchanges, want 1", name, len(f.Exchanges))
72		}
73		return f.Exchanges[0]
74	}
75	
76	// The premises every verdict below rests on, read from the fixtures.
77	func TestMeasuredRESTAnswersHoldThePremises(t *testing.T) {
78		fixtures := restFixtures(t)
79	
80		// Criterion 3: the generic endpoint answers 200 to all three accounts, names
81		// the type, and carries no memberNames anywhere (so step 2 of DetectGroup is
82		// always reached for a group).
83		for _, tc := range []struct{ repo, typ string }{{restGroup, "group"}, {restHosted, "hosted"}, {restProxy, "proxy"}} {
84			for _, id := range restIdentities {
85				ex := restExchange(t, fixtures, genericFixture(tc.repo, id))
86				if ex.Status != http.StatusOK {
87					t.Errorf("%s generic as %s: status %d, want 200", tc.repo, id, ex.Status)
88				}
89				var doc struct {
90					Type  string `json:"type"`
91					Group any    `json:"group"`
92					Attrs struct {
93						Group any `json:"group"`
94					} `json:"attributes"`
95				}
96				if err := json.Unmarshal(ex.Body, &doc); err != nil {
97					t.Fatalf("%s generic as %s: %v", tc.repo, id, err)
98				}
99				if doc.Type != tc.typ {
100					t.Errorf("%s generic as %s: type %q, want %q", tc.repo, id, doc.Type, tc.typ)
101				}
102				if doc.Group != nil || doc.Attrs.Group != nil {
103					t.Errorf("%s generic as %s carries a group document: DetectGroup would stop at step 1", tc.repo, id)
104				}
105			}
106		}
107	
108		// The detailed endpoint of the group: 200 with the members for admin, 403
109		// with no body for anonymous, and 404 "Repository not found" (not 403) for the
110		// pull account (C1 of the DEVDESK-511 plan, decided by the user).
111		admin := restExchange(t, fixtures, detailedFixture(restGroup, nexusfixture.Admin))
112		if admin.Status != http.StatusOK {
113			t.Errorf("detailed as admin: status %d, want 200", admin.Status)
114		}
115		if got := memberNamesOf(t, admin.Body); !reflect.DeepEqual(got, []string{restHosted, restProxy}) {
116			t.Errorf("detailed as admin: memberNames %v, want [%s %s]", got, restHosted, restProxy)
117		}
118		anon := restExchange(t, fixtures, detailedFixture(restGroup, nexusfixture.Anonymous))
119		if anon.Status != http.StatusForbidden || len(anon.Body) != 0 {
120			t.Errorf("detailed as anonymous: %d %q, want 403 with no body", anon.Status, anon.Body)
121		}
122		pull := restExchange(t, fixtures, detailedFixture(restGroup, nexusfixture.Pull))
123		if pull.Status != http.StatusNotFound || !strings.Contains(string(pull.Body), "Repository not found") {
124			t.Errorf("detailed as pull: %d %q, want 404 \"Repository not found\"", pull.Status, pull.Body)
125		}
126	}
127	
128	func memberNamesOf(t *testing.T, body []byte) []string {
129		t.Helper()
130		var doc struct {
131			Group struct {
132				MemberNames []string `json:"memberNames"`
133			} `json:"group"`
134		}
135		if err := json.Unmarshal(body, &doc); err != nil {
136			t.Fatalf("reading memberNames: %v", err)
137		}
138		return doc.Group.MemberNames
139	}
140	
141	// restInfo is the registry an identity would have configured for a repository
142	// served by the fake, reached by the path form of a Nexus URL.
143	func restInfo(s *fakenexus.Server, repo string, id nexusfixture.Identity) RegistryInfo {
144		info := RegistryInfo{Provider: ProviderNexus, URL: s.URL(restHost) + "/repository/" + repo}
145		if id != nexusfixture.Anonymous {
146			info.Username, info.Password = fakenexus.User(id), fakenexus.Password
147		}
148		return info
149	}
150	
151	// wantHits fails unless each named fixture answered exactly the given number of
152	// requests and nothing else answered any.
153	func wantHits(t *testing.T, s *fakenexus.Server, fixtures map[string]nexusfixture.Fixture, want map[string]int) {
154		t.Helper()
155		total, wantTotal := 0, 0
156		for name := range fixtures {
157			total += s.Hits(name)
158		}
159		for name, n := range want {
160			wantTotal += n
161			if got := s.Hits(name); got != n {
162				t.Errorf("Hits(%s) = %d, want %d", name, got, n)
163			}
164		}
165		if total != wantTotal {
166			t.Errorf("%d requests answered in total, want %d", total, wantTotal)
167		}
168	}
169	
170	// The group's two members, as the admin's detailed answer lists them (F2: both
171	// aliases come out as "docker", the -hosted and -proxy suffixes being stripped).
172	func measuredMembers(s *fakenexus.Server) []GroupMember {
173		return []GroupMember{
174			{Alias: "docker", URL: s.URL(restHost), RepoPrefix: restHosted},
175			{Alias: "docker", URL: s.URL(restHost), RepoPrefix: restProxy},
176		}
177	}
178	
179	func TestDetectGroupOnMeasuredNexusAnswers(t *testing.T) {
180		fixtures := restFixtures(t)
181		all := make([]nexusfixture.Fixture, 0, len(fixtures))
182		for _, f := range fixtures {
183			all = append(all, f)
184		}
185	
186		t.Run("group as admin lists its members", func(t *testing.T) {
187			s := fakenexus.New(t, all...)
188			id := nexusfixture.Admin
189	
190			members, err := (&NexusDetector{}).DetectGroup(context.Background(), restInfo(s, restGroup, id))
191	
192			if err != nil {
193				t.Fatalf("err = %v, want nil", err)
194			}
195			if want := measuredMembers(s); !reflect.DeepEqual(members, want) {
196				t.Errorf("members = %+v, want %+v", members, want)
197			}
198			wantHits(t, s, fixtures, map[string]int{genericFixture(restGroup, id): 1, detailedFixture(restGroup, id): 1})
199		})
200	
201		t.Run("group as anonymous is refused, 403", func(t *testing.T) {
202			s := fakenexus.New(t, all...)
203			id := nexusfixture.Anonymous
204	
205			members, err := (&NexusDetector{}).DetectGroup(context.Background(), restInfo(s, restGroup, id))
206	
207			wantRefused(t, members, err, http.StatusForbidden, true)
208			// No credential, so no anonymous retry: one request on the detailed endpoint.
209			wantHits(t, s, fixtures, map[string]int{genericFixture(restGroup, id): 1, detailedFixture(restGroup, id): 1})
210		})
211	
212		// C1 (DEVDESK-511 plan, decided by the user): the pull account does not get
213		// the 403 that D161 (NX-07) assumed on the detailed endpoint, it gets 404
214		// "Repository not found" (rest-repositories-group-docker-group--pull). DevDesk
215		// types only 401 and 403 as a refusal, so today this is a FAILED discovery:
216		// the UI says the manager is unreachable, writes nothing to the group cache
217		// and asks again every time, and never says "denied".
218		//
219		// This test pins that CURRENT behavior on the real answer. It is not the
220		// wanted one: DEVDESK-578 (NX-07b, "a 404 on a group's detailed endpoint is a
221		// refusal") changes it, and flips this test with it.
222		t.Run("group as the pull account is a failed discovery today, DEVDESK-578", func(t *testing.T) {
223			s := fakenexus.New(t, all...)
224			id := nexusfixture.Pull
225	
226			members, err := (&NexusDetector{}).DetectGroup(context.Background(), restInfo(s, restGroup, id))
227	
228			wantFailedDiscovery(t, members, err)
229			var se *oci.StatusError
230			if !errors.As(err, &se) || se.Code != http.StatusNotFound || se.Source != oci.SourceManagementAPI {
231				t.Errorf("err = %v, want errors.As *oci.StatusError{404, management API}", err)
232			}
233			if strings.Contains(err.Error(), fakenexus.Password) {
234				t.Errorf("error leaks the password: %v", err)
235			}
236			// The account's 404, then D156's anonymous retry, which the anonymous
237			// recording answers with its 403: the first attempt decides, so the 403 is
238			// not what the error reports.
239			wantHits(t, s, fixtures, map[string]int{
240				genericFixture(restGroup, id):                      1,
241				detailedFixture(restGroup, id):                     1,
242				detailedFixture(restGroup, nexusfixture.Anonymous): 1,
243			})
244		})
245	
246		// A hosted or a proxy repository says what it is on the generic endpoint, and
247		// that is the end of it: not a group, no detailed request.
248		for _, repo := range []string{restHosted, restProxy} {
249			for _, id := range restIdentities {
250				t.Run(repo+" as "+string(id)+" is not a group", func(t *testing.T) {
251					s := fakenexus.New(t, all...)
252	
253					members, err := (&NexusDetector{}).DetectGroup(context.Background(), restInfo(s, repo, id))
254	
255					if err != nil || members != nil {
256						t.Fatalf("DetectGroup = (%v, %v), want (nil, nil): not a group is a settled answer", members, err)
257					}
258					wantHits(t, s, fixtures, map[string]int{genericFixture(repo, id): 1})
259				})
260			}
261		}
262	}
